<?php
session_start(); include 'conexion.php';
if (!isset($_SESSION['id_usuario'])) { header('Location: login.php'); exit(); }
if ($_SESSION['rol'] !== 'especialista' && $_SESSION['rol'] !== 'administrador') { header('Location: dashboard.php'); exit(); }
$id_usuario=(int)$_SESSION['id_usuario']; $rol=$_SESSION['rol'];
function h($v){ return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function audit_fm($conn,$tabla,$id,$accion,$descripcion,$usuario,$antes=null,$nuevos=null){
 $ip=$_SERVER['REMOTE_ADDR']??''; $ua=$_SERVER['HTTP_USER_AGENT']??''; $a=$antes?json_encode($antes,JSON_UNESCAPED_UNICODE):null; $n=$nuevos?json_encode($nuevos,JSON_UNESCAPED_UNICODE):null;
 $stmt=$conn->prepare("INSERT INTO fm_auditoria (tabla_afectada,id_registro_afectado,accion,descripcion,datos_anteriores,datos_nuevos,id_usuario,ip_usuario,user_agent) VALUES (?,?,?,?,?,?,?,?,?)");
 if($stmt){$stmt->bind_param('sissssiss',$tabla,$id,$accion,$descripcion,$a,$n,$usuario,$ip,$ua);$stmt->execute();$stmt->close();}
}
$id_tipo=(int)($_GET['id_tipo_ficha'] ?? $_POST['id_tipo_ficha'] ?? 0);
if($id_tipo<=0){ header('Location: especialista_crear_fichas.php'); exit(); }
$stmt=$conn->prepare("SELECT * FROM fm_tipos_ficha WHERE id=? LIMIT 1"); $stmt->bind_param('i',$id_tipo); $stmt->execute(); $ficha=$stmt->get_result()->fetch_assoc(); $stmt->close(); if(!$ficha){ header('Location: especialista_crear_fichas.php'); exit(); }
$mensaje=''; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $accion=$_POST['accion']??'';
 try{
  if($accion==='crear_prorroga'){
    $alcance=$_POST['alcance']??'TODAS'; $id_ie=null; if($alcance==='IE') $id_ie=(int)($_POST['id_institucion']??0); if($alcance==='IE' && $id_ie<=0) throw new Exception('Selecciona una institución educativa.');
    $original=$ficha['fecha_limite'] ?: date('Y-m-d H:i:s'); $nueva=trim($_POST['nueva_fecha_limite']??''); $motivo=trim($_POST['motivo']??''); if($nueva==='') throw new Exception('La nueva fecha límite es obligatoria.'); if($motivo==='') throw new Exception('El motivo de la prórroga es obligatorio.');
    $nuevaDB=str_replace('T',' ',$nueva); if(strlen($nuevaDB)===16) $nuevaDB.=':00';
    $stmt=$conn->prepare("INSERT INTO fm_prorrogas (id_tipo_ficha,id_institucion,fecha_limite_original,nueva_fecha_limite,motivo,estado,creado_por) VALUES (?,?,?,?,?,'ACTIVA',?)");
    $stmt->bind_param('iisssi',$id_tipo,$id_ie,$original,$nuevaDB,$motivo,$id_usuario); $stmt->execute(); $id=$stmt->insert_id; $stmt->close();
    audit_fm($conn,'fm_prorrogas',$id,'CREAR_PRORROGA','Creó prórroga de ficha de monitoreo.',$id_usuario,null,['id_tipo_ficha'=>$id_tipo,'id_institucion'=>$id_ie,'nueva_fecha_limite'=>$nuevaDB]); $mensaje='Prórroga creada correctamente.';
  }
  if($accion==='inactivar_prorroga'){
    $id=(int)($_POST['id_prorroga']??0); $stmt=$conn->prepare("UPDATE fm_prorrogas SET estado='INACTIVA' WHERE id=? AND id_tipo_ficha=?"); $stmt->bind_param('ii',$id,$id_tipo); $stmt->execute(); $stmt->close();
    audit_fm($conn,'fm_prorrogas',$id,'INACTIVAR','Inactivó una prórroga.',$id_usuario); $mensaje='Prórroga inactivada.';
  }
 }catch(Exception $e){ $error=$e->getMessage(); }
}
$stmt=$conn->prepare("SELECT nombres,ape_pat,ape_mat,dni FROM usuarios WHERE id=? LIMIT 1"); $stmt->bind_param('i',$id_usuario); $stmt->execute(); $user=$stmt->get_result()->fetch_assoc(); $stmt->close(); $nombreUsuario=trim(($user['nombres']??'').' '.($user['ape_pat']??'').' '.($user['ape_mat']??''));
$ies=$conn->query("SELECT id, nombre_ie, codigo_institucion, codigo_local, distrito FROM instituciones ORDER BY nombre_ie ASC");
$prorrogas=$conn->query("SELECT p.*, i.nombre_ie, i.codigo_institucion, i.codigo_local FROM fm_prorrogas p LEFT JOIN instituciones i ON i.id=p.id_institucion WHERE p.id_tipo_ficha=$id_tipo ORDER BY p.fecha_creacion DESC");
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Prórrogas</title><link href="assets/lib/bootstrap/bootstrap.min.css" rel="stylesheet"><link href="assets/lib/bootstrap-icons/bootstrap-icons.css" rel="stylesheet">
<link rel="stylesheet" href="assets/lib/tabler-icons/tabler-icons.min.css">
<link rel="stylesheet" href="assets/css/fluent.css"><style>:root{--main-green:#198754;--dark-green:#006633;--bg:#f8fdf9}body{background:var(--bg);font-family:'Segoe UI',Tahoma,sans-serif}.page-title{color:#08783f;font-weight:800}.card-soft{border:1px solid #cfe8da;border-radius:16px;box-shadow:0 8px 20px rgba(0,0,0,.06);background:white;overflow:hidden}.card-head{background:#006633;color:white;padding:18px 22px;font-weight:800}.form-label{font-weight:700;color:#08783f}.table thead th{background:#f3faf5;color:#064e3b}</style></head><body>
<nav class="navbar navbar-expand navbar-light ugel-topbar sticky-top"><div class="container-fluid px-4"><a class="navbar-brand d-flex align-items-center gap-2" href="dashboard_especialista.php"><i class="bi bi-shield-check ugel-brand-icon"></i><div class="d-flex flex-column lh-1"><span class="ugel-brand-title">GESTIÓN DE DOCUMENTOS</span><small class="ugel-brand-subtitle">Sistema IE · Especialista</small></div></a><div class="d-flex align-items-center gap-2 ms-auto"><a class="btn profile-btn d-flex align-items-center gap-1" href="dashboard_especialista.php"><i class="bi bi-house-door me-1"></i> Inicio</a><div class="dropdown"><button class="btn ugel-profile-button dropdown-toggle d-flex align-items-center gap-2" type="button" data-bs-toggle="dropdown"><div class="text-end lh-sm"><small class="d-block text-uppercase"><?= h(strtoupper($rol)) ?></small><strong><?= h($user['nombres'] ?? 'Usuario') ?></strong></div><i class="bi bi-person-circle ugel-profile-avatar fs-4"></i></button><ul class="dropdown-menu dropdown-menu-end ugel-profile-menu p-4 mt-2 shadow"><li class="text-center mb-4"><div class="mb-2"><i class="bi bi-person-vcard fs-2 text-success"></i></div><h6 class="fw-bold mb-1 text-success"><?= h($nombreUsuario) ?></h6><small class="text-muted">DNI: <?= h($user['dni'] ?? '') ?></small></li><li><hr class="dropdown-divider my-3"></li><li><a class="btn btn-outline-primary ugel-menu-action w-100 fw-bold mb-2" href="panel_usuario.php"><i class="bi bi-person"></i> <span>Perfil</span></a></li><li><a class="btn btn-outline-danger ugel-menu-action w-100 fw-bold" href="logout.php"><i class="bi bi-box-arrow-right"></i> <span>Cerrar sesión</span></a></li></ul></div></div></div></nav>
<main class="container-fluid px-4 py-4"><div class="d-flex justify-content-between align-items-center flex-wrap gap-3 mb-4"><div><h2 class="page-title mb-1"><i class="bi bi-calendar-plus me-2"></i>Prórrogas</h2><div class="text-muted"><?= h($ficha['nombre']) ?> · Fecha límite original: <strong><?= h($ficha['fecha_limite'] ?: 'No definida') ?></strong></div></div><div><a href="especialista_crear_fichas.php" class="btn btn-outline-success fw-bold"><i class="bi bi-arrow-left"></i> Volver al panel</a></div></div><?php if($mensaje): ?><div class="alert alert-success"><?= h($mensaje) ?></div><?php endif; ?><?php if($error): ?><div class="alert alert-danger"><?= h($error) ?></div><?php endif; ?>
<div class="row g-4"><div class="col-lg-4"><div class="card-soft"><div class="card-head">Nueva prórroga</div><div class="p-3"><form method="post"><input type="hidden" name="accion" value="crear_prorroga"><input type="hidden" name="id_tipo_ficha" value="<?= $id_tipo ?>"><div class="mb-3"><label class="form-label">Alcance</label><select name="alcance" id="alcance" class="form-select"><option value="TODAS">Todas las I.E.</option><option value="IE">Una I.E. específica</option></select></div><div class="mb-3" id="boxIe" style="display:none"><label class="form-label">Institución educativa</label><select name="id_institucion" class="form-select"><option value="">Seleccionar I.E.</option><?php while($ie=$ies->fetch_assoc()): ?><option value="<?= (int)$ie['id'] ?>"><?= h($ie['nombre_ie']) ?> <?= $ie['codigo_institucion']?'('.h($ie['codigo_institucion']).')':'' ?></option><?php endwhile; ?></select></div><div class="mb-3"><label class="form-label">Nueva fecha límite *</label><input type="datetime-local" name="nueva_fecha_limite" class="form-control" required></div><div class="mb-3"><label class="form-label">Motivo *</label><textarea name="motivo" class="form-control" rows="4" required></textarea></div><button class="btn btn-success fw-bold w-100" onclick="return confirm('¿Crear esta prórroga?');"><i class="bi bi-save"></i> Crear prórroga</button></form></div></div></div><div class="col-lg-8"><div class="card-soft"><div class="card-head">Prórrogas registradas</div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Alcance</th><th>Nueva fecha</th><th>Motivo</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php if($prorrogas && $prorrogas->num_rows): while($p=$prorrogas->fetch_assoc()): ?><tr><td><?= $p['id_institucion']?h($p['nombre_ie']):'<strong>Todas las I.E.</strong>' ?></td><td><?= h($p['nueva_fecha_limite']) ?></td><td><?= h($p['motivo']) ?></td><td><span class="badge <?= $p['estado']==='ACTIVA'?'bg-success':'bg-secondary' ?>"><?= h($p['estado']) ?></span></td><td><?php if($p['estado']==='ACTIVA'): ?><form method="post" onsubmit="return confirm('¿Inactivar esta prórroga?');"><input type="hidden" name="accion" value="inactivar_prorroga"><input type="hidden" name="id_tipo_ficha" value="<?= $id_tipo ?>"><input type="hidden" name="id_prorroga" value="<?= (int)$p['id'] ?>"><button class="btn btn-sm btn-outline-danger">Inactivar</button></form><?php endif; ?></td></tr><?php endwhile; else: ?><tr><td colspan="5" class="text-center text-muted py-4">No hay prórrogas registradas.</td></tr><?php endif; ?></tbody></table></div></div></div></div></main>
<script src="assets/lib/bootstrap/bootstrap.bundle.min.js"></script><script>const a=document.getElementById('alcance'), b=document.getElementById('boxIe'); a.addEventListener('change',()=>{b.style.display=a.value==='IE'?'block':'none'});</script></body></html>
